SourceCode.Declaration:
class METVendInvoiceMatching
{
    VendInvoiceInfoTable claimInvoiceTable;
    VendInvoiceInfoTable vendInvoiceInfoTable;


}

Method.Source:
    public VendInvoiceInfoTable parmVendInvoiceInfoTable(VendInvoiceInfoTable _vendInvoiceInfoTable = vendInvoiceInfoTable)
    {
        vendInvoiceInfoTable = _vendInvoiceInfoTable;

        return vendInvoiceInfoTable;
    }

public static METVendInvoiceMatching construct()
{
    return new METVendInvoiceMatching();
}

    public void generateFailureMatchingLines()
    {
        VendInvoiceInfoLine     vendInvoiceInfoLine;
        VendInvoiceInfoSubLine  vendInvoiceInfoSubLine;

        boolean                 failureLinesRun;

        ttsbegin;

        this.updateMarkupTransTaxItemGroup();

        while select forupdate vendInvoiceInfoLine
                where   vendInvoiceInfoLine.ParmId          == vendInvoiceInfoTable.ParmId &&
                        vendInvoiceInfoLine.TableRefId      == vendInvoiceInfoTable.TableRefId
            exists join vendInvoiceInfoSubLine
                where   vendInvoiceInfoSubLine.LineRefRecId == vendInvoiceInfoLine.RecId
        {
            if(vendInvoiceInfoLine.matchingVarianceStatus(vendInvoiceInfoTable) == LastMatchVarianceOptions::Warning &&
                !vendInvoiceInfoLine.MetAutoApprove)
            {
                if(vendInvoiceInfoLine.MetMultiple)
                {
                    this.createFailureMatchingLine(vendInvoiceInfoLine, true, true);
                    this.createFailureMatchingLine(vendInvoiceInfoLine, false, true);

                    vendInvoiceInfoLine.resetReceiptedInvoiceLine();
                }
                else
                {
                    if(vendInvoiceInfoLine.priceVarianceStatus() == LastMatchVarianceOptions::Warning)
                    {
                        this.createFailureMatchingLine(vendInvoiceInfoLine, false);

                        vendInvoiceInfoLine.resetReceiptedInvoiceLine();
                    }
                    else if(vendInvoiceInfoLine.checkIfQuantityMatch() == LastMatchVarianceOptions::Warning &&
                            (vendInvoiceInfoLine.ReceiveNow > vendInvoiceInfoLine.purchQtyMatched() ||
                                vendInvoiceInfoLine.PdsCWReceiveNow > vendInvoiceInfoLine.pdsCWQtyMatched()))
                    {
                        this.createFailureMatchingLine(vendInvoiceInfoLine, true);

                        vendInvoiceInfoLine.resetReceiptedInvoiceLine();
                    }
                }
            }

            if(!failureLinesRun)
                failureLinesRun = true;
        }


        if(failureLinesRun)
        {
            this.updateMarkupTransTaxItemGroup();
            this.createVarianceInvoiceLines();
            this.updateMarkupTransTaxItemGroup();
            this.updateVarianceApproved();
        }

        ttscommit;

        this.saveInvoices();
    }

    private void updateVarianceApproved()
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;

        select firstonly vendInvoiceInfoLine
            where   vendInvoiceInfoLine.ParmId      == vendInvoiceInfoTable.ParmId &&
                    vendInvoiceInfoLine.TableRefId  == vendInvoiceInfoTable.TableRefId &&
                    vendInvoiceInfoLine.MetAutoApprove;

        if(vendInvoiceInfoLine)
        {
            vendInvoiceInfoTable.selectForUpdate(true);
            vendInvoiceInfoTable.VarianceApproved = NoYes::Yes;
            vendInvoiceInfoTable.update();
        }
    }

    private void saveInvoices(boolean _isClaimInvoice = false)
    {
        PurchParmUpdate purchParmUpdateLocal;
        
        purchParmUpdateLocal = PurchParmUpdate::find(vendInvoiceInfoTable.ParmId, true);
        if (purchParmUpdateLocal.numberOfTables() == 1)
        {
            purchParmUpdateLocal.delete();
        }

        if(_isClaimInvoice)
        {
            VendInvoiceInfoTable::moveFromSavedToActive(vendInvoiceInfoTable, vendInvoiceInfoTable.ParmId);
        }
        else
        {
            VendInvoiceInfoTable::moveFromActiveToSaved(vendInvoiceInfoTable);
        }
    }

    private void createFailureMatchingLine(VendInvoiceInfoLine _vendInvoiceInfoLine, boolean _isQtyFailure, boolean _multipleFailure = false)
    {
        ReasonTable             reason;
        VendInvoiceInfoLine     failureInvoiceLine;
        boolean                 useCatchWeight          = _vendInvoiceInfoLine.PdsCWReceiveNow ? true : false;
        PurchLine               purchLine               = _vendInvoiceInfoLine.purchLine();

        if(_multipleFailure)
        {
            Query query = _vendInvoiceInfoLine.metInvoiceMatchingReasonQuery(!_isQtyFailure, _isQtyFailure, useCatchWeight, _multipleFailure);

            if(query)
            {
                QueryRun queryRun = new QueryRun(query);

                if(queryRun.next())
                {
                    reason = queryRun.get(tableNum(ReasonTable));
                }
            }
        }
        else
        {
            reason = ReasonTable::find(ReasonTableRef::find(_vendInvoiceInfoLine.ReasonTableRef).Reason);
        }

        if(reason)
        {
            failureInvoiceLine.initPriceFailureMatchingLine(_vendInvoiceInfoLine, reason, _isQtyFailure, useCatchWeight);
            
            if(failureInvoiceLine.validateWrite())
            {
                failureInvoiceLine.insert();
            }
        }
    }

    protected void updateMarkupTransTaxItemGroup()
    {
        VendInvoiceInfoLine vendInvoiceInfoLine;
        MarkupTrans         markupTrans;

        while select forupdate markupTrans
                where markupTrans.TransTableId  == tableNum(VendInvoiceInfoLine) &&
                      markupTrans.TaxItemGroup  == ''
            join vendInvoiceInfoLine
                where markupTrans.TransRecId            == vendInvoiceInfoLine.RecId &&
                      vendInvoiceInfoLine.ParmId        == vendInvoiceInfoTable.ParmId &&
                      vendInvoiceInfoLine.TableRefId    == vendInvoiceInfoTable.TableRefId
        {
            markupTrans.TaxItemGroup = vendInvoiceInfoLine.TaxItemGroup;
            markupTrans.update();
        }
    }

    protected void createVarianceInvoiceLines()
    {
        VendParameters      vendParameters = VendParameters::find();
        MetVariance         varianceAmount = vendInvoiceInfoTable.displayMetVariance();
        ReasonTable         reasonTable    = ReasonTable::find(vendParameters.METReasonCode);

        VendInvoiceInfoLine vendInvoiceInfoLine, varianceLine;
        Amount              amount;
        InventDim           inventDim;

        if(varianceAmount)
        {
            while select TaxItemGroup, sum(LineAmount) from vendInvoiceInfoLine
                group by TaxItemGroup
            where
                vendInvoiceInfoLine.ParmId      == vendInvoiceInfoTable.ParmId &&
                vendInvoiceInfoLine.TableRefId  == vendInvoiceInfoTable.TableRefId
            {
                amount = (vendInvoiceInfoLine.LineAmount/vendInvoiceInfoTable.MetImportAmount) * varianceAmount;

                varianceLine.clear();
                varianceLine.initValue();

                varianceLine.ParmId                 = vendInvoiceInfoTable.ParmId;
                varianceLine.TableRefId             = vendInvoiceInfoTable.TableRefId;
                varianceLine.currencyCode           = vendInvoiceInfoTable.currencyCode;
                varianceLine.AddressRefRecId        = vendInvoiceInfoTable.AddressRefRecId;
                varianceLine.AddressRefTableId      = vendInvoiceInfoTable.AddressRefTableId;
                varianceLine.DeliveryName           = vendInvoiceInfoTable.DeliveryName;
                varianceLine.DeliveryPostalAddress  = vendInvoiceInfoTable.DeliveryPostalAddress;
        
                varianceLine.ItemId                 = vendParameters.METVarianceItem;
                varianceLine.modifiedField(fieldNum(VendInvoiceInfoLine, ItemId));

                varianceLine.MetClaimLine           = reasonTable.METClaim;
                varianceLine.MetExtComment          = reasonTable.MetExtComment;
            
                varianceLine.TaxGroup               = vendInvoiceInfoTable.purchTable().TaxGroup;
                varianceLine.TaxItemGroup           = vendInvoiceInfoLine.TaxItemGroup;
                

                inventDim.InventSiteId              = vendInvoiceInfoTable.purchTable().InventSiteId;
                inventDim.InventLocationId          = vendInvoiceInfoTable.purchTable().InventLocationId;
            
                varianceLine.InventDimId            = InventDim::findOrCreate(inventDim).inventDimId;

                varianceLine.ReasonTableRef         = ReasonTableRef::createReasonTableRef(reasonTable.Reason, reasonTable.Description);

                varianceLine.PurchPrice             = abs(amount);
                varianceLine.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

                varianceLine.ReceiveNow = amount > 0 ? 1 : -1;

                varianceLine.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(UnknownNoYes::Yes);

                if(varianceLine.validateWrite())
                {
                    varianceLine.insert();
                }
            }
        }
    }

    public void createClaimInvoice()
    {
        VendInvoiceInfoLine vendInvoiceLine;

        ttsbegin;

        this.createClaimInvoiceHeader(vendInvoiceInfoTable);

        if(this.claimInvoiceTable)
        {
            while select forupdate vendInvoiceLine
                        where vendInvoiceLine.ParmId        == vendInvoiceInfoTable.ParmId &&
                              vendInvoiceLine.TableRefId    == vendInvoiceInfoTable.TableRefId
            {
                if(vendInvoiceLine.isNonPO() && vendInvoiceLine.MetClaimLine)
                {
                    this.createClaimLine(vendInvoiceLine);
                }
            }
        }

        ttscommit;

        this.saveInvoices(true);
        this.submitClaimInvoiceToWorkflow();
    }

private void submitClaimInvoiceToWorkflow()
{
    if(claimInvoiceTable && claimInvoiceTable.existLine() && claimInvoiceTable.canSubmitToWorkflow())
    {
        VendInvoiceHeaderWorkflow::submitToWorkflow(claimInvoiceTable, claimInvoiceTable.Description);
    }
}

    private void createClaimLine(VendInvoiceInfoLine _invoiceLine)
    {
        VendInvoiceInfoLine claimLine;

        claimLine.clear();
        claimLine.initValue();

        claimLine.ParmId                 = claimInvoiceTable.ParmId;
        claimLine.TableRefId             = claimInvoiceTable.TableRefId;
        claimLine.currencyCode           = _invoiceLine.currencyCode;
        claimLine.AddressRefRecId        = _invoiceLine.AddressRefRecId;
        claimLine.AddressRefTableId      = _invoiceLine.AddressRefTableId;
        claimLine.DeliveryName           = _invoiceLine.DeliveryName;
        claimLine.DeliveryPostalAddress  = _invoiceLine.DeliveryPostalAddress;
        claimLine.MetTransRefId          = _invoiceLine.RecId;
        
        claimLine.ItemId                 = _invoiceLine.ItemId;
        claimLine.modifiedField(fieldNum(VendInvoiceInfoLine, ItemId));

        claimLine.MetExtComment          = _invoiceLine.MetExtComment;
            
        claimLine.TaxGroup               = _invoiceLine.TaxGroup;
        claimLine.TaxItemGroup           = _invoiceLine.TaxItemGroup;
        claimLine.DefaultDimension       = _invoiceLine.DefaultDimension;
        claimLine.InventDimId            = _invoiceLine.InventDimId;

        claimLine.ReasonTableRef         = _invoiceLine.ReasonTableRef;
        claimLine.Description            = _invoiceLine.Description;

        claimLine.PurchPrice             = _invoiceLine.PurchPrice;
        claimLine.modifiedField(fieldNum(VendInvoiceInfoLine, PurchPrice));

        claimLine.ReceiveNow            = _invoiceLine.ReceiveNow * -1;
        claimLine.PdsCWReceiveNow       = _invoiceLine.PdsCWReceiveNow * -1;

        claimLine.vendDocumentLineInterface().modifiedReceiveNowWithPromptDefault(abs(claimLine.PdsCWReceiveNow) > 0, UnknownNoYes::Yes);

        if(claimLine.validateWrite())
        {
            claimLine.insert();
        }
    }

    private void createClaimInvoiceHeader(VendInvoiceInfoTable _originalInvoice)
    {
        VendInvoiceInfoSubTable     vendInvoiceInfoSubTable;

        claimInvoiceTable.clear();
        claimInvoiceTable.initValue();
        claimInvoiceTable.initFromActiveHeader(_originalInvoice);

        claimInvoiceTable.DocumentOrigin    = DocumentOrigin::Manual;
        claimInvoiceTable.defaultRow(null, null, true);
        claimInvoiceTable.ParmId                = formletterParmData::getNewParmId();
        claimInvoiceTable.TableRefId            = formletterParmData::getNewTableRefId();
        claimInvoiceTable.ImportedAmount        = 0;
        claimInvoiceTable.ImportedSalesTax      = 0;

        claimInvoiceTable.Num = strFmt("%1 - %2", _originalInvoice.Num, METConstants::VendInvoiceInfoCreditNoteSuffix);
        claimInvoiceTable.Description = strFmt("@MET:ClaimInvoiceDescription",_originalInvoice.Num, _originalInvoice.PurchId);

        if(claimInvoiceTable.validateWrite())
        {
            claimInvoiceTable.insert();

            vendInvoiceInfoSubTable.clear();
            vendInvoiceInfoSubTable.initValue();
            vendInvoiceInfoSubTable.defaultRow();
 
            vendInvoiceInfoSubTable.ParmId      = claimInvoiceTable.ParmId;
            vendInvoiceInfoSubTable.OrigPurchId = claimInvoiceTable.PurchId;
            vendInvoiceInfoSubTable.PurchName   = claimInvoiceTable.PurchName;
            vendInvoiceInfoSubTable.TableRefId  = claimInvoiceTable.TableRefId;
 
            vendInvoiceInfoSubTable.insert();
        }
        
    }
